    "id": "pyrevit-filter-copy-bytype",
    "title": "Filter Override — Copy Specific Overrides by Type",
    "category": "pyRevit",
    "categoryLabel": "Revit pyRevit",
    "version": "v2.0",
    "date": "2024-11-02",
    "compatibility": "Revit 2020 – 2026",
    "command": "pyRevit > LUDARP > FilterOverride > Copybytype",
    "status": "Production",
    "isUpcoming": false,
