    "id": "pyrevit-calculator-history",
    "title": "Revit Calculator & History Logger",
    "category": "pyRevit",
    "categoryLabel": "Revit pyRevit",
    "version": "v2.0",
    "date": "2024-11-02",
    "compatibility": "Revit 2020 – 2026",
